('SUBJ-TJ-GOV-001', 'Министерство энергетики и водных ресурсов Таджикистана', 'Ministry of Energy and Water Resources of Tajikistan', 'Министерство энергетики и водных ресурсов Таджикистана', 'Ministry of Energy and Water Resources of Tajikistan', 'National water and energy authority for Tajikistan', 'Государственное министерство', 'Dushanbe', 'Tajikistan', NULL, 'info@water.tj.gov', 38.5598, 68.787, 'government_ministry', ARRAY['government','tajikistan','ministry','energy']::text[]),
('SUBJ-TJ-CORP-001', 'Компания Барқи Тоҷик', 'Barqi Tojik', 'Компания Барқи Тоҷик', 'Barqi Tojik', 'Central Asia''s largest hydroelectric power generator', 'Гидроэлектрическая компания', 'Dushanbe', 'Tajikistan', NULL, NULL, 38.5598, 68.787, 'hydroelectric_corporation', ARRAY['company','hydroelectric','tajikistan','power']::text[]),
('SUBJ-KG-GOV-001', 'Министерство энергетики Киргизии', 'Ministry of Energy of Kyrgyzstan', 'Министерство энергетики Киргизии', 'Ministry of Energy of Kyrgyzstan', 'National energy and water authority for Kyrgyzstan', 'Государственное министерство', 'Bishkek', 'Kyrgyzstan', NULL, 'info@energy.kg.gov', 42.8746, 74.5698, 'government_ministry', ARRAY['government','kyrgyzstan','energy','hydroelectric']::text[]),
('SUBJ-KG-CORP-001', 'Компания Кыргызэнерго', 'Kyrgyzhydropower Company', 'Компания Кыргызэнерго', 'Kyrgyzhydropower Company', 'Central Asia''s regional power supplier', 'Гидроэлектрическая компания', 'Bishkek', 'Kyrgyzstan', NULL, NULL, 42.8746, 74.5698, 'hydroelectric_corporation', ARRAY['company','hydroelectric','kyrgyzstan','regional']::text[]),
('SUBJ-INT-UN-001', 'ООН-Вода', 'UN-Water', 'ООН-Вода', 'UN-Water', 'UN inter-agency coordination mechanism for all freshwater-related issues. Coordinates the work of UN system on water and sanitation, leads implementation of SDG 6 (Clean Water and Sanitation).', 'Агентство ООН', 'Geneva, Switzerland', 'International', 'www.unwater.org', 'unwater@un.org', 46.2044, 6.1432, 'un_agency', ARRAY['un','international','coordination','sdg6','global','freshwater']::text[]),
('SUBJ-INT-UN-002', 'ЮНЕП — Отдел пресноводных экосистем', 'UNEP — Freshwater Ecosystems Unit', 'ЮНЕП — Отдел пресноводных экосистем', 'UNEP — Freshwater Ecosystems Unit', 'United Nations Environment Programme leads global environmental action including freshwater ecosystems, transboundary water governance and the UN World Water Development Report co-authorship. Manages the Global Environmental Monitoring System for water (GEMS/Water).', 'Агентство ООН', 'Nairobi, Kenya', 'International', 'www.unep.org/explore-topics/water', NULL, -1.2921, 36.8219, 'un_agency', ARRAY['un','environment','freshwater','ecosystems','monitoring','global']::text[]),
('SUBJ-INT-UN-003', 'ЮНЕСКО — Международная гидрологическая программа', 'UNESCO — International Hydrological Programme (IHP)', 'ЮНЕСКО — Международная гидрологическая программа', 'UNESCO — International Hydrological Programme (IHP)', 'UNESCO''s International Hydrological Programme is the only intergovernmental programme in the UN system devoted to water research, water resources management, and education and capacity building. Covers 193 member states and manages the WHYCOS (World Hydrological Cycle Observing System).', 'Агентство ООН', 'Paris, France', 'International', 'www.unesco.org/en/natural-sciences/environment/water/ihp', NULL, 48.8462, 2.3059, 'un_agency', ARRAY['un','unesco','hydrology','research','education','global','groundwater']::text[]),
('SUBJ-INT-UN-004', 'ВОЗ — Вода, санитария и гигиена', 'WHO — Water, Sanitation and Hygiene (WASH)', 'ВОЗ — Вода, санитария и гигиена', 'WHO — Water, Sanitation and Hygiene (WASH)', 'World Health Organization''s WASH division sets global drinking water quality guidelines (WHO Guidelines for Drinking-Water Quality), tracks drinking water and sanitation coverage worldwide and leads the JMP (Joint Monitoring Programme for Water Supply and Sanitation) together with UNICEF.', 'Агентство ООН', 'Geneva, Switzerland', 'International', 'www.who.int/teams/environment-climate-change-and-health/water-sanitation-and-health', NULL, 46.2338, 6.137, 'un_agency', ARRAY['un','who','health','drinking-water','sanitation','guidelines','global']::text[]),
('SUBJ-INT-UN-005', 'ЮНИСЕФ — Программа WASH', 'UNICEF — WASH Programme', 'ЮНИСЕФ — Программа WASH', 'UNICEF — WASH Programme', 'UNICEF''s WASH programme works in over 100 countries to improve access to safe water, sanitation and hygiene for children and families. Co-leads the Joint Monitoring Programme (JMP) for Water Supply and Sanitation. Reaches over 13 million people per year with improved water access.', 'Агентство ООН', 'New York, USA', 'International', 'www.unicef.org/wash', NULL, 40.7489, -73.968, 'un_agency', ARRAY['un','unicef','wash','children','sanitation','hygiene','global']::text[]),
('SUBJ-INT-NGO-001', 'WWF — Глобальная программа пресных вод', 'WWF — Global Freshwater Programme', 'WWF — Глобальная программа пресных вод', 'WWF — Global Freshwater Programme', 'WWF''s freshwater programme protects rivers, lakes, wetlands and the species that depend on them. It covers 35 priority freshwater ecoregions globally, advocates for sustainable water governance and leads the Living Planet Index tracking freshwater biodiversity. The programme''s Water Risk Filter is used by 1,200+ businesses.', 'Международная НКО', 'Gland, Switzerland', 'International', 'www.worldwildlife.org/initiatives/freshwater', NULL, 46.4167, 6.2667, 'international_ngo', ARRAY['ngo','conservation','freshwater','biodiversity','rivers','wetlands','global']::text[]),
('SUBJ-INT-NGO-002', 'Water.org', 'Water.org', 'Water.org', 'Water.org', 'Water.org (co-founded by Matt Damon and Gary White) pioneers market-based approaches to achieve safe water and sanitation access for those living in poverty. The WaterCredit initiative leverages microfinance loans — since 1990 it has reached 60+ million people in 15 countries across Africa, Asia and Latin America.', 'Международная НКО', 'Kansas City, Missouri, USA', 'USA', 'www.water.org', 'info@water.org', 39.0997, -94.5786, 'international_ngo', ARRAY['ngo','water-access','microfinance','sanitation','developing-world','usa']::text[]),
('SUBJ-INT-NGO-003', 'WaterAid', 'WaterAid', 'WaterAid', 'WaterAid', 'WaterAid is an international NGO specialising exclusively in water, sanitation and hygiene. Active in 28 countries, it has reached over 28 million people with clean water since 1981. Advocates at global policy level (UN, G7, G20) for universal WASH access and climate-resilient water infrastructure.', 'Международная НКО', 'London, UK', 'United Kingdom', 'www.wateraid.org', 'supporter.care@wateraid.org', 51.5, -0.119, 'international_ngo', ARRAY['ngo','wash','water-access','sanitation','africa','asia','uk']::text[]),
('SUBJ-INT-NGO-004', 'Глобальное водное партнёрство', 'Global Water Partnership (GWP)', 'Глобальное водное партнёрство', 'Global Water Partnership (GWP)', 'Global Water Partnership is an intergovernmental organisation promoting integrated water resources management (IWRM). Network of 3,000+ partner organisations in 179 countries, 13 regional water partnerships. Supports governments in translating IWRM principles into national water policy and plans.', 'Международная НКО', 'Stockholm, Sweden', 'Sweden', 'www.gwp.org', 'gwp@gwp.org', 59.3293, 18.0686, 'international_ngo', ARRAY['ngo','iwrm','governance','policy','global','network','climate']::text[]),
('SUBJ-INT-NGO-005', 'Всемирный водный совет', 'World Water Council', 'Всемирный водный совет', 'World Water Council', 'International multi-stakeholder platform that organises the World Water Forum every 3 years — the largest international gathering on water (10,000+ participants, 170 countries). Brings together governments, international institutions, academics, private sector and civil society to address global water challenges.', 'Международная НКО', 'Marseille, France', 'France', 'www.worldwatercouncil.org', 'wwc@worldwatercouncil.org', 43.2965, 5.3698, 'international_ngo', ARRAY['ngo','forum','policy','diplomacy','global','multi-stakeholder']::text[]),
('SUBJ-INT-NGO-006', 'Greenpeace — Кампания за воду и океаны', 'Greenpeace — Water & Oceans Campaign', 'Greenpeace — Кампания за воду и океаны', 'Greenpeace — Water & Oceans Campaign', 'Greenpeace campaigns globally against water pollution from industrial agriculture, plastics, mining and fossil fuels. The Detox Water campaign pressured 80+ brands to eliminate hazardous chemicals from supply chains affecting waterways. The Defending Our Rivers programme covers the Amazon, Congo and Mekong basins.', 'Международная НКО', 'Amsterdam, Netherlands', 'Netherlands', 'www.greenpeace.org/international/act/water', NULL, 52.374, 4.8897, 'international_ngo', ARRAY['ngo','environment','pollution','advocacy','rivers','oceans','global']::text[]),
('SUBJ-INT-CORP-001', 'Veolia Water Technologies & Solutions', 'Veolia Water Technologies & Solutions', 'Veolia Water Technologies & Solutions', 'Veolia Water Technologies & Solutions', 'Veolia is the world''s largest water services company. Operates water and wastewater services for 100+ million people across 5 continents. Provides water treatment design, engineering, O&M services, and cutting-edge technologies including membrane filtration, UV disinfection, smart metering and digital water management platforms (HUBGRADE).', 'Международная водная корпорация', 'Paris, France', 'France', 'www.veolia.com', NULL, 48.8566, 2.3522, 'water_corporation', ARRAY['corporation','water-services','treatment','utilities','france','global','desalination']::text[]),
('SUBJ-INT-CORP-002', 'SUEZ — Водоснабжение и управление отходами', 'SUEZ — Water & Waste Management', 'SUEZ — Водоснабжение и управление отходами', 'SUEZ — Water & Waste Management', 'SUEZ provides water and wastewater services to 66 million people globally. Specialises in water treatment solutions, digital water management (AqPulse), membrane technology (ZeeWeed), and water recycling. After divestiture from Veolia (2022), SUEZ Water Technologies & Solutions was acquired by INEOS and continues as a leading water technology group.', 'Международная водная корпорация', 'Paris, France', 'France', 'www.suez.com', NULL, 48.8566, 2.3522, 'water_corporation', ARRAY['corporation','water-services','treatment','membrane','france','global']::text[]),
('SUBJ-INT-CORP-003', 'Xylem Inc.', 'Xylem Inc.', 'Xylem Inc.', 'Xylem Inc.', 'Xylem is a leading global water technology company that solves the world''s most challenging water issues. Products and services cover transport, treatment, testing, and digital solutions. Brands include Flygt (submersible pumps), Sensus (smart metering), Wedeco (UV disinfection), YSI (water quality testing), and Pure Technologies (pipeline inspection).', 'Технологическая водная компания', 'Washington, DC, USA', 'USA', 'www.xylem.com', NULL, 38.9072, -77.0369, 'water_technology_company', ARRAY['corporation','technology','pumps','smart-metering','digital','usa','global']::text[]),
('SUBJ-INT-CORP-004', 'Watts Water Technologies', 'Watts Water Technologies', 'Watts Water Technologies', 'Watts Water Technologies', 'Watts Water Technologies manufactures products for residential, commercial and industrial water systems: flow control, water quality, plumbing, HVAC and gas components. Key product lines include backflow preventers, pressure regulators, thermostatic valves, and water treatment systems. Sells to 100+ countries.', 'Технологическая водная компания', 'North Andover, Massachusetts, USA', 'USA', 'www.wattswater.com', NULL, 42.6976, -71.1328, 'water_technology_company', ARRAY['corporation','water-systems','flow-control','residential','commercial','usa']::text[]),
('SUBJ-INT-CORP-005', 'IDEXX Laboratories — Водный отдел', 'IDEXX Laboratories (Water Division)', 'IDEXX Laboratories — Водный отдел', 'IDEXX Laboratories (Water Division)', 'IDEXX Water provides industry-leading water microbiology test kits and instruments used by water utilities, regulators and labs in 170+ countries. Products include Colilert (E. coli and total coliform testing), Enterolert (enterococci), Pseudalert (Pseudomonas), and Quanti-Tray systems for precise quantification.', 'Компания тестирования воды', 'Westbrook, Maine, USA', 'USA', 'www.idexx.com/en/water', NULL, 43.6759, -70.3726, 'water_testing_company', ARRAY['corporation','water-testing','microbiology','laboratory','coliform','usa','global']::text[]),
('SUBJ-INT-CORP-006', 'Kurita Water Industries', 'Kurita Water Industries', 'Kurita Water Industries', 'Kurita Water Industries', 'Kurita Water Industries is a Japan-based global leader in water treatment chemicals, equipment and services. Serves industrial customers in power generation, steel, electronics, food & beverage, and municipal water. Provides total water management solutions including ultra-pure water for semiconductor manufacturing. Strong presence in Asia-Pacific.', 'Технологическая водная компания', 'Tokyo, Japan', 'Japan', 'www.kurita.co.jp/english', NULL, 35.6762, 139.6503, 'water_technology_company', ARRAY['corporation','water-treatment','chemicals','industrial','japan','asia-pacific']::text[]),
('SUBJ-INT-CORP-007', 'Jacobs Engineering — Вода и окружающая среда', 'Jacobs Engineering — Water & Environment', 'Jacobs Engineering — Вода и окружающая среда', 'Jacobs Engineering — Water & Environment', 'Jacobs is one of the world''s largest water engineering and consulting firms. The Water & Environment practice delivers design, construction management and programme management for drinking water, wastewater, stormwater, dams, desalination and water reuse. Notable projects include Thames Tideway Tunnel (UK), Neom desalination (Saudi Arabia) and nationwide US infrastructure programmes.', 'Инженерная компания', 'Dallas, Texas, USA', 'USA', 'www.jacobs.com/markets/water', NULL, 32.7767, -96.797, 'engineering_company', ARRAY['engineering','consulting','design','desalination','wastewater','dams','usa','global']::text[]),
('SUBJ-INT-CORP-008', 'AECOM — Водный бизнес', 'AECOM — Water Business Line', 'AECOM — Водный бизнес', 'AECOM — Water Business Line', 'AECOM''s Water business delivers planning, design, programme management and construction management for drinking water, wastewater, flood risk, coastal resilience and stormwater projects. One of the top 3 water engineering firms worldwide, active in over 150 countries with landmark projects including the Jubail Industrial City water system (Saudi Arabia).', 'Инженерная компания', 'Los Angeles, California, USA', 'USA', 'www.aecom.com/water', NULL, 34.0522, -118.2437, 'engineering_company', ARRAY['engineering','consulting','design','flood-management','stormwater','usa','global']::text[]),
('SUBJ-INT-RES-001', 'Тихоокеанский институт (Pacific Institute)', 'Pacific Institute', 'Тихоокеанский институт (Pacific Institute)', 'Pacific Institute', 'Pacific Institute is an independent non-partisan think tank creating and advancing solutions to the world''s most pressing water challenges. Publishes the influential Water Conflict Chronology, the Climate Change and Water reports, and advises governments and businesses on sustainable water use and water-energy nexus.', 'Научно-исследовательский институт', 'Oakland, California, USA', 'USA', 'www.pacinst.org', 'info@pacinst.org', 37.8044, -122.2711, 'research_institute', ARRAY['research','think-tank','policy','conflict','climate','usa','global']::text[]),
('SUBJ-INT-RES-002', 'Стокгольмский международный водный институт (SIWI)', 'Stockholm International Water Institute (SIWI)', 'Стокгольмский международный водный институт (SIWI)', 'Stockholm International Water Institute (SIWI)', 'SIWI generates evidence and drives policy change for equitable and sustainable water use. Organises World Water Week in Stockholm — the world''s leading annual conference on water issues. Manages the Stockholm Water Prize and Junior Water Prize. Provides technical assistance to governments in Africa, Asia and the Middle East.', 'Научно-исследовательский институт', 'Stockholm, Sweden', 'Sweden', 'www.siwi.org', 'siwi@siwi.org', 59.3293, 18.0686, 'research_institute', ARRAY['research','policy','conference','governance','global','sweden']::text[]),
('SUBJ-INT-RES-003', 'IHE Delft — Институт водного образования', 'IHE Delft — Institute for Water Education', 'IHE Delft — Институт водного образования', 'IHE Delft — Institute for Water Education', 'IHE Delft is the world''s largest international graduate water education facility. Offers MSc programmes in water management, sanitation, hydraulic engineering and water governance. Has awarded 21,000+ master''s degrees to water professionals from 165 countries. UNESCO Category 1 centre.', 'Научно-исследовательский институт', 'Delft, Netherlands', 'Netherlands', 'www.un-ihe.org', 'info@un-ihe.org', 52.0116, 4.3571, 'research_institute', ARRAY['research','education','graduate','capacity-building','netherlands','global','un']::text[]),
('SUBJ-INT-RES-004', 'CGIAR — Вода, земля и экосистемы', 'CGIAR — Water, Land and Ecosystems (WLE)', 'CGIAR — Вода, земля и экосистемы', 'CGIAR — Water, Land and Ecosystems (WLE)', 'CGIAR''s Water, Land and Ecosystems programme is hosted by IWMI (International Water Management Institute). Conducts research in 30+ developing countries on food-water-land security, irrigation, groundwater, basin water management and nature-based solutions. Works directly with smallholder farmers and national governments to increase water productivity.', 'Научно-исследовательский институт', 'Colombo, Sri Lanka', 'International', 'www.iwmi.cgiar.org', NULL, 6.9271, 79.8612, 'research_institute', ARRAY['research','agriculture','irrigation','groundwater','developing-world','food-security']::text[]),
('SUBJ-US-GOV-001', 'Агентство по охране окружающей среды США — Управление водных ресурсов', 'US EPA — Office of Water', 'Агентство по охране окружающей среды США — Управление водных ресурсов', 'US EPA — Office of Water', 'The US EPA Office of Water implements the Clean Water Act and Safe Drinking Water Act. Regulates drinking water quality for 300+ million Americans, sets water quality standards for rivers and lakes, manages the Clean Water State Revolving Fund ($5 billion/year), and oversees NPDES (National Pollutant Discharge Elimination System) permits for 450,000+ facilities.', 'Государственное агентство', 'Washington, DC, USA', 'USA', 'www.epa.gov/aboutepa/epa-offices-and-regions', NULL, 38.8711, -77.0141, 'government_agency', ARRAY['government','regulation','drinking-water','clean-water','usa','federal']::text[]),
('SUBJ-EU-GOV-001', 'Водная рамочная директива ЕС — ГД по окружающей среде', 'EU Water Framework Directive — DG Environment', 'Водная рамочная директива ЕС — ГД по окружающей среде', 'EU Water Framework Directive — DG Environment', 'The EU Water Framework Directive (WFD, 2000/60/EC) is the cornerstone of European water policy. Requires all EU Member States to achieve ''good ecological status'' of all water bodies by 2027. DG Environment implements WFD, the Floods Directive, the Drinking Water Directive (2020) and the Urban Wastewater Treatment Directive. Covers 28 river basin management plans across 27 member states.', 'Государственное агентство', 'Brussels, Belgium', 'Belgium', 'environment.ec.europa.eu/topics/water_en', NULL, 50.8503, 4.3517, 'government_agency', ARRAY['government','eu','regulation','rivers','drinking-water','floods','europe']::text[]),
('SUBJ-CN-GOV-001', 'Министерство водного хозяйства Китая', 'Ministry of Water Resources of China (MWR)', 'Министерство водного хозяйства Китая', 'Ministry of Water Resources of China (MWR)', 'China''s Ministry of Water Resources (MWR) oversees all national water policy, river basin commissions, flood control and drought relief. Manages the South-to-North Water Diversion Project — the world''s largest water transfer infrastructure — plus 98,000+ reservoirs and 420,000 km of levees. China invests $100+ billion annually in water infrastructure.', 'Государственное министерство', 'Beijing, China', 'China', 'www.mwr.gov.cn', NULL, 39.9042, 116.4074, 'government_ministry', ARRAY['government','ministry','china','infrastructure','diversion','rivers','dams']::text[]),
('SUBJ-IN-GOV-001', 'Министерство Джал Шакти Индии', 'Jal Shakti Ministry — India', 'Министерство Джал Шакти Индии', 'Jal Shakti Ministry — India', 'India''s Jal Shakti Ministry (created 2019 by merging two ministries) manages water resources, river development and Ganga rejuvenation. Runs Jal Jeevan Mission targeting tap water to every rural household by 2024, NMCG (National Mission for Clean Ganga), and PMKSY (Pradhan Mantri Krishi Sinchai Yojana) irrigation mission. India has the world''s largest irrigation system — 90 million hectares.', 'Государственное министерство', 'New Delhi, India', 'India', 'www.jalshakti-dowr.gov.in', NULL, 28.6139, 77.209, 'government_ministry', ARRAY['government','ministry','india','irrigation','ganga','rural-water','asia']::text[]),
('SUBJ-INT-TECH-001', 'Cambrian Innovation', 'Cambrian Innovation', 'Cambrian Innovation', 'Cambrian Innovation', 'Cambrian Innovation develops biological water and wastewater treatment systems powered by clean energy. Their EcoVolt product line converts industrial wastewater organic content into biogas that powers treatment, achieving carbon-neutral and sometimes carbon-negative operation. Serves breweries, food & beverage, and cannabis industries.', 'Водная технологическая компания', 'Boston, Massachusetts, USA', 'USA', 'www.cambrianinnovation.com', NULL, 42.3601, -71.0589, 'water_tech_startup', ARRAY['startup','technology','wastewater','biogas','clean-energy','circular','usa']::text[]),
('SUBJ-INT-TECH-002', 'WaterGen', 'WaterGen', 'WaterGen', 'WaterGen', 'WaterGen is a global leader in atmospheric water generation (AWG) technology — extracting drinking water directly from air humidity. Products range from portable units (1-3 litres/hour) to large industrial generators (6,000 litres/day). Deployed in disaster relief, remote areas, military and industrial settings in 50+ countries. Temperature range: 15-40°C, RH from 20%.', 'Водная технологическая компания', 'Petah Tikva, Israel', 'Israel', 'www.watergen.com', NULL, 32.0878, 34.8878, 'water_tech_startup', ARRAY['startup','technology','atmospheric-water','drinking-water','israel','innovation','humanitarian']::text[]),
('SUBJ-INT-TECH-003', 'Gradiant Corporation', 'Gradiant Corporation', 'Gradiant Corporation', 'Gradiant Corporation', 'Gradiant is a global water solutions company for industrial-grade applications — semiconductor manufacturing, oil & gas, pharmaceuticals, mining and power. Technologies include Carrier-Gas Extraction (CGE) for brine concentration, Selective Contaminant Extraction (SCE) for PFAS/heavy metals, and Biological Ion Exchange for nutrient removal. Backed by SoftBank Vision Fund.', 'Водная технологическая компания', 'Boston, Massachusetts, USA', 'USA', 'www.gradiant.com', NULL, 42.3601, -71.0589, 'water_tech_startup', ARRAY['startup','technology','industrial','ultrapure-water','pfas','zero-liquid-discharge','usa']::text[]),
('SUBJ-INT-TECH-004', 'Epic Cleantec', 'Epic Cleantec', 'Epic Cleantec', 'Epic Cleantec', 'Epic Cleantec builds on-site building water reuse systems — capturing greywater and blackwater within large commercial buildings and converting them to non-potable (and potable) reuse water at the point of generation. Systems are embedded in a building''s mechanical infrastructure and can reduce a building''s municipal water demand by up to 95%.', 'Водная технологическая компания', 'San Francisco, California, USA', 'USA', 'www.epiccleantec.com', NULL, 37.7749, -122.4194, 'water_tech_startup', ARRAY['startup','technology','water-reuse','greywater','buildings','circular','usa']::text[]),
('SUBJ-INT-TECH-005', 'Origen Water', 'Origen Water', 'Origen Water', 'Origen Water', 'Origen Water develops electrochemical water treatment systems that eliminate the use of chemicals in disinfection and scale prevention. Their ATLAS platform uses advanced electrochemistry for municipal and commercial water treatment — eliminating chlorine, antiscalants and biocides. Particularly relevant for water-scarce regions seeking chemical-free water management.', 'Водная технологическая компания', 'Colorado, USA', 'USA', 'www.origenwater.com', NULL, 39.5501, -105.7821, 'water_tech_startup', ARRAY['startup','technology','electrochemical','disinfection','chemical-free','usa']::text[]),
('SUBJ-INT-TECH-006', 'Xylem Vue — Цифровые инновации', 'Xylem Vue (Innovation Arm)', 'Xylem Vue — Цифровые инновации', 'Xylem Vue (Innovation Arm)', 'Xylem Vue is Xylem''s digital platform and innovation accelerator — integrating AI, IoT sensors and data analytics across the full water cycle. Combines Xylem''s acquisition of Evoqua and Idrica (Smart Water platform) to deliver predictive maintenance, network optimization, leakage reduction and energy efficiency for water utilities. Active in 20+ countries.', 'Водная технологическая компания', 'Atlanta, Georgia, USA', 'USA', 'www.xylem.com/en-us/products--services/digital-solutions/xylem-vue', NULL, 33.749, -84.388, 'water_tech_startup', ARRAY['startup','digital','ai','iot','smart-water','utilities','usa']::text[]),
('SUBJ-INT-BANK-001', 'Всемирный банк — Глобальная практика по воде', 'World Bank — Water Global Practice', 'Всемирный банк — Глобальная практика по воде', 'World Bank — Water Global Practice', 'The World Bank Water Global Practice is the largest external financier of water supply and sanitation in the developing world — approving $5-7 billion/year in water-related projects. Supports 170+ countries on water security, sanitation, flood risk, dams, irrigation and water governance. The ''2023 Water Security Diagnostic'' covers 180+ countries. Manages $3.7 billion Water Sector Reform Trust Fund.', 'Многосторонний банк развития', 'Washington, DC, USA', 'USA', 'www.worldbank.org/en/topic/water', NULL, 38.899, -77.043, 'multilateral_development_bank', ARRAY['development-bank','financing','water-security','wash','dams','irrigation','global']::text[]),
('SUBJ-INT-BANK-002', 'Азиатский банк развития — Водное финансирование', 'Asian Development Bank — Water Financing Partnership Facility', 'Азиатский банк развития — Водное финансирование', 'Asian Development Bank — Water Financing Partnership Facility', 'ADB''s Water Financing Partnership Facility (WFPF) mobilises concessional co-financing for water projects in Asia-Pacific. ADB approves $3-4 billion/year for water — the programme covers urban water supply, rural WASH, irrigation modernisation, river basin management and flood risk reduction. The 2022 programme ''From Glaciers to Fields'' covers 9 Central Asian countries.', 'Многосторонний банк развития', 'Manila, Philippines', 'Philippines', 'www.adb.org/what-we-do/themes/water/overview', NULL, 14.5548, 121.0244, 'multilateral_development_bank', ARRAY['development-bank','financing','central-asia','irrigation','floods','asia-pacific']::text[]),
('SUBJ-INT-BANK-003', 'ЕБРР — Муниципальная и экологическая инфраструктура', 'EBRD — Municipal & Environmental Infrastructure', 'ЕБРР — Муниципальная и экологическая инфраструктура', 'EBRD — Municipal & Environmental Infrastructure', 'The EBRD''s Municipal & Environmental Infrastructure group is the primary financier of water and wastewater projects in transition economies (Eastern Europe, Central Asia, MENA). Invests €800M–1.2B/year in water, financing modernisation of water utilities, NRW reduction, energy efficiency and climate resilience in 38 countries including Kazakhstan, Ukraine, Uzbekistan, Moldova and Turkey.', 'Многосторонний банк развития', 'London, UK', 'United Kingdom', 'www.ebrd.com/what-we-do/sectors/municipal-environmental-infrastructure.html', NULL, 51.5141, -0.0817, 'multilateral_development_bank', ARRAY['development-bank','financing','central-asia','eastern-europe','utilities','nrw','climate']::text[]);
